"""
Simple evaluation script for the autoppia_operator /act endpoint.

Uses TaskExecutionSession from autoppia_iwa and calls the local agent
HTTP API directly (no autoppia_rl dependencies).
"""

import asyncio
import base64
import contextlib
import hashlib
import json
import os
import re
from datetime import datetime
import random
import subprocess
import socket
import sys
import time
from typing import Any
from copy import deepcopy
from pathlib import Path
from collections import defaultdict
import aiohttp
import httpx

# ── Ensure the operator repo is on sys.path ─────────────────────
SCRIPT_DIR = Path(__file__).resolve().parent
OPERATOR_ROOT = SCRIPT_DIR.parent
sys.path.insert(0, str(OPERATOR_ROOT))
sys.path.insert(0, str(SCRIPT_DIR))

from src.operator.support.utils import candidate_text as _shared_candidate_text
from src.operator.support.utils import normalize_selector_payload as _shared_normalize_selector_payload

# ── Load .env from autoppia_operator ────────────────────────────
from dotenv import load_dotenv

operator_env = SCRIPT_DIR / ".env"
if operator_env.exists():
    load_dotenv(operator_env, override=True)


def _candidate_text(value: Any) -> str:
    if isinstance(value, str):
        return " ".join(value.strip().split())
    if isinstance(value, (int, float, bool)):
        return str(value)
    if isinstance(value, list):
        for item in value:
            parsed = _candidate_text(item)
            if parsed:
                return parsed
    if isinstance(value, dict):
        for key in ("value", "text", "label", "name", "query"):
            parsed = _candidate_text(value.get(key))
            if parsed:
                return parsed
    return ""


def _normalize_selector_payload(raw_selector: Any) -> dict[str, Any] | None:
    if not isinstance(raw_selector, dict):
        return None
    selector = dict(raw_selector)
    raw_type = str(selector.get("type") or "").strip()
    sel_type = raw_type.lower()
    case_sensitive = bool(selector.get("case_sensitive", False))

    def first_text(*keys: str) -> str:
        for key in keys:
            value = _candidate_text(selector.get(key))
            if value:
                return value[:400]
        return ""

    if sel_type in {"text", "textselector", "textcontains", "textcontainsselector", "linktext", "partiallinktext"}:
        value = first_text("value", "text", "label", "name", "query")
        if not value:
            return None
        return {"type": "tagContainsSelector", "value": value, "case_sensitive": case_sensitive}
    if sel_type in {"attribute", "attributevalueselector"}:
        attribute = first_text("attribute", "attr", "name")
        value = first_text("value", "text", "label")
        if not attribute or not value:
            return None
        return {
            "type": "attributeValueSelector",
            "attribute": attribute,
            "value": value,
            "case_sensitive": case_sensitive,
        }
    if sel_type == "xpathselector":
        value = first_text("value", "text", "xpath")
        if value.lower().startswith("xpath="):
            value = value[6:].strip()
        if value.startswith("///"):
            value = "//" + value.lstrip("/")
        elif value.startswith("/") and not value.startswith("//"):
            value = value.lstrip("/")
        value = re.sub(r"\s+", " ", value).strip()
        if not value:
            return None
        return {"type": "xpathSelector", "value": value, "case_sensitive": case_sensitive}
    if sel_type == "tagcontainsselector":
        value = first_text("value", "text", "label")
        if not value:
            return None
        return {"type": "tagContainsSelector", "value": value, "case_sensitive": case_sensitive}
    if sel_type in {"id", "class", "name", "href", "placeholder", "aria-label", "aria_label", "title", "role", "value", "type"}:
        value = first_text("value", "text", "label")
        if not value:
            return None
        attribute = "aria-label" if sel_type == "aria_label" else raw_type
        return {
            "type": "attributeValueSelector",
            "attribute": attribute,
            "value": value,
            "case_sensitive": case_sensitive,
        }
    if sel_type not in {"attributevalueselector", "tagcontainsselector", "xpathselector"}:
        attribute = first_text("attribute", "attr", "name")
        value = first_text("value", "text", "label", "query")
        if attribute and value:
            return {
                "type": "attributeValueSelector",
                "attribute": attribute,
                "value": value,
                "case_sensitive": case_sensitive,
            }
        if value:
            return {"type": "tagContainsSelector", "value": value, "case_sensitive": case_sensitive}
        return None
    return selector


def _sanitize_action_payload(payload: dict[str, Any]) -> dict[str, Any]:
    out = dict(payload)
    selector = _normalize_selector_payload(out.get("selector"))
    if isinstance(selector, dict):
        out["selector"] = selector
    elif "selector" in out:
        out.pop("selector", None)
    return out

